// applyBuiltinLengths 遍历 builtinLengths, 把每个限定名解析为实际的内建
// 函数/方法对象并设置规范的 length 自有属性 (SetFunctionLength: 不可写、
// 不可枚举、可配置)。解析失败的键静默跳过 (如引擎未实现的命名空间)。
//
// 应在 SetupGlobals 末尾 (所有内建注册完毕后) 调用一次。
func applyBuiltinLengths(env *runtime.Environment) {
	for path, n := range builtinLengths {
		segs := splitDots(path)
		if len(segs) == 0 {
			continue
		}
		v, ok := env.Get(segs[0])
		if !ok || v == nil {
			continue
		}
		resolved := true
		for _, seg := range segs[1:] {
			obj, isObj := v.(*object.Object)
			if !isObj {
				// BuiltinFunction.prototype 等也可继续走 GetProperty
				if getter, hasGet := v.(interface{ GetProperty(string) (object.Value, bool) }); hasGet {
					nv, got := getter.GetProperty(seg)
					if !got || nv == nil {
						resolved = false
						break
					}
					v = nv
					continue
				}
				resolved = false
				break
			}
			nv, got := obj.GetProperty(seg)
			if !got || nv == nil {
				resolved = false
				break
			}
			v = nv
		}
		if !resolved {
			continue
		}
		switch fn := v.(type) {
		case *object.BuiltinFunction:
			fn.SetFunctionLength(n)
		case *object.BuiltinMethod:
			fn.SetFunctionLength(n)
		}
	}
}

// splitDots 按 '.' 切分限定名 (键已保证不含 Symbol/$262 等)。
func splitDots(s string) []string {
	out := []string{}
	cur := ""
	for _, r := range s {
		if r == '.' {
			out = append(out, cur)
			cur = ""
			continue
		}
		cur += string(r)
	}
	if cur != "" {
		out = append(out, cur)
	}
	return out
}
